// t: [số ô (1-4), nội dung, lý do (tùy chọn)]. p: h = học sinh, s = sinh viên, a = dùng chung.
const D=[
{"s": "Sáng mai kiểm tra 15 phút môn Anh và nộp bài tập lớn môn Văn. Thi cuối kỳ còn 3 tuần. Bạn cùng lớp nhắn hỏi gấp một câu có thể tự tra Google.", "t": [[1, "Ôn kiểm tra Anh ngày mai"], [1, "Hoàn thành bài tập Văn"], [2, "Bắt đầu ôn dần cho thi cuối kỳ"], [3, "Trả lời bạn ngắn gọn, không sa đà"]], "tip": "2 việc cùng gấp là bình thường. Quan trọng là chọn việc nào làm trước, không phải hoảng loạn.", "p": "h"},
{"s": "Chiều nay nộp bài thực hành Tin học. Bạn muốn luyện gõ 10 ngón để làm bài nhanh hơn về sau, sắp xếp lại góc học tập cho gọn, và có video hài bạn bè vừa gửi.", "t": [[1, "Nộp bài thực hành đúng hạn"], [2, "Luyện gõ 10 ngón"], [2, "Sắp xếp lại góc học tập"], [4, "Xem video hài"]], "tip": "Không có việc nào ở ô ⚡. Không phải lúc nào cũng có yếu tố “giả khẩn cấp”.", "p": "a"},
{"s": "Chiều rảnh, không có deadline gấp. Có lịch tự học tuần sau, việc tập thể dục hay bị trì hoãn, tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng (hối đăng ký hôm nay) và cám dỗ lướt mạng.", "t": [[2, "Đọc trước bài học tuần sau", "Chưa phải làm ngay, nhưng đọc trước giúp tiếp thu bài tuần sau dễ hơn."], [2, "Tập thể dục 30 phút"], [3, "Cân nhắc kỹ, không vội đăng ký vì bị hối"], [4, "Lướt mạng không mục đích"]], "tip": "Ngày không có việc gấp là cơ hội tốt nhất để đầu tư cho ô 🌱. Đừng để ⚡ và 🗑️ chiếm hết.", "p": "a"},
{"s": "Mai thi Toán, ngày kia nộp tiểu luận Sử, và người thân trong nhà bị ốm cần người chăm tối nay. Phòng hơi bừa nhưng không ảnh hưởng gì.", "t": [[1, "Ôn thi Toán"], [1, "Hoàn thành tiểu luận Sử"], [1, "Chăm sóc người thân bị ốm"], [4, "Dọn phòng (để sau cũng được)"]], "tip": "Tuần thật sự căng với 3 việc 🔥. Kỹ năng cần có là chọn việc nào làm trước, không phải né cả 3.", "p": "h"},
{"s": "Bài tập nhóm nộp tối nay và bạn phụ trách phần cuối. Bạn cũng muốn tìm hiểu định hướng nghề nghiệp. Nhóm chat lớp đang bàn chuyện phiếm liên tục, và có quảng cáo game mời tải ngay hôm nay để nhận quà.", "t": [[1, "Hoàn thành phần bài tập nhóm"], [2, "Tìm hiểu định hướng tương lai"], [3, "Tắt thông báo nhóm chat, đọc gộp sau"], [3, "Bỏ qua quảng cáo game"]], "tip": "2 nguồn xao nhãng cùng lúc rất thực tế. Hãy xử lý gộp, đừng phản ứng từng cái.", "p": "a"},
{"s": "Ngày mai là hạn chót nộp phiếu đăng ký môn/khối cho học kỳ sau. Bạn muốn chọn cho đúng, tránh chọn sai.", "t": [[1, "Nộp phiếu đăng ký đúng hạn"], [2, "Tìm hiểu kỹ các môn/khối"], [2, "Hỏi ý kiến thầy cô, anh chị đi trước"], [2, "Tự đánh giá điểm mạnh, điểm yếu"]], "tip": "3/4 việc là ô 🌱. Một quyết định lớn cần chuẩn bị kỹ, không chỉ điền form cho xong.", "p": "h"},
{"s": "Giáo viên đã báo trước: tuần này có thể kiểm tra miệng bất chợt. Bài thu hoạch nộp chiều nay. Bạn nhắn mượn vở nhưng không nói khi nào cần. Bàn học cũng đang lộn xộn.", "t": [[1, "Ôn bài đề phòng kiểm tra miệng bất chợt"], [1, "Hoàn thành bài thu hoạch chiều nay"], [3, "Trả lời bạn mượn vở sau"], [4, "Dọn bàn học"]], "tip": "Việc “có thể xảy ra bất chợt” vẫn xếp 🔥 vì rủi ro cao nếu không chuẩn bị.", "p": "h"},
{"s": "Cuối tuần thong thả, không có việc học nào gấp. Có 2 tin nhắn mời hoạt động không quan trọng nhưng đều “cần trả lời hôm nay”, và 2 hoạt động giải trí đơn thuần.", "t": [[3, "Trả lời tin nhắn mời thứ nhất"], [3, "Trả lời tin nhắn mời thứ hai"], [4, "Xem phim"], [4, "Chơi game"]], "tip": "Không có ô 🔥/🌱. Một ngày nghỉ hợp lý cũng là quản lý thời gian tốt, miễn là không lạm dụng.", "p": "a"},
{"s": "Giữa hai kỳ thi, chưa có deadline gấp. Bạn có thể học bổ sung phần còn yếu, rèn kỹ năng mềm, nghỉ ngơi có kế hoạch sau kỳ thi, hoặc cày một series phim dài tập không giới hạn.", "t": [[2, "Học bổ sung kiến thức còn yếu"], [2, "Rèn kỹ năng mềm"], [2, "Nghỉ ngơi tái tạo năng lượng có giới hạn thời gian"], [4, "Xem phim dài tập không giới hạn"]], "tip": "Nghỉ ngơi có chủ đích, có giới hạn là 🌱. Xem phim không giới hạn là 🗑️ vì dễ mất kiểm soát thời gian.", "p": "a"},
{"s": "Tối nay không có deadline học tập, nhưng có 3 thứ dồn dập: cuộc gọi chào mời, tin nhắn nhờ vả không thật sự cần thiết, thông báo quảng cáo giật tít giới hạn thời gian. Bạn muốn đọc thêm sách mở rộng kiến thức.", "t": [[3, "Từ chối cuộc gọi chào mời"], [3, "Từ chối khéo lời nhờ vả không cần thiết"], [3, "Bỏ qua quảng cáo giật tít"], [2, "Đọc thêm sách/tài liệu mở rộng"]], "tip": "3/4 việc là ⚡. Buổi tối “yên tĩnh giả tạo” này thử xem bạn có giữ được ưu tiên thật không.", "p": "a"},
{"s": "Mai kiểm tra Lý. Cổng đăng ký thi thử học sinh giỏi/học bổng đóng tối nay. Bạn cũng cần lập lịch ôn cho các môn còn lại trong tháng và rèn thói quen ngủ đủ giấc mùa thi.", "t": [[1, "Ôn kiểm tra Lý"], [1, "Đăng ký thi thử trước khi đóng cổng"], [2, "Lập lịch ôn tập tháng tới"], [2, "Rèn thói quen ngủ đủ giấc"]], "tip": "Không có ⚡/🗑️ lần này: một ngày bận nhưng “sạch”, chỉ cần sắp xếp đúng thứ tự.", "p": "h"},
{"s": "Bạn cần nộp đơn xin nghỉ một buổi (lý do chính đáng) trước 9h sáng mai. Bạn cùng lớp rủ chụp ảnh theo trào lưu đang hot, “làm ngay kẻo hết trend”. Bạn cũng định xem lại video giải trí cũ và sắp xếp album ảnh điện thoại.", "t": [[1, "Nộp đơn xin nghỉ trước hạn"], [3, "Cân nhắc, không vội chạy theo trend"], [4, "Xem lại video cũ"], [4, "Sắp xếp album ảnh"]], "tip": "Không có việc 🌱 lần này. Không phải lúc nào cũng có việc đầu tư dài hạn, và điều đó bình thường.", "p": "h"},
{"s": "Hôm nay không có deadline gấp. Bạn muốn bắt đầu học một kỹ năng mới theo mục tiêu dài hạn. Điện thoại liên tục báo thông báo mạng xã hội, một người quen nhắn nhờ việc không liên quan đến bạn bằng giọng rất gấp, và bạn cũng muốn nằm nghỉ 15 phút.", "t": [[2, "Học kỹ năng mới theo mục tiêu dài hạn"], [3, "Tắt bớt thông báo mạng xã hội"], [3, "Từ chối khéo việc nhờ vả không liên quan"], [4, "Nằm nghỉ ngơi 15 phút"]], "tip": "Không có 🔥. Đây là bài test “ngày rảnh”: bạn đầu tư cho 🌱 hay bị ⚡ cuốn đi? Nghỉ ngơi có chừng mực là bình thường, chỉ xấu khi thay thế hoàn toàn việc quan trọng.", "p": "a"},
{"s": "Mai có buổi phỏng vấn/thi vấn đáp quan trọng (học bổng, CLB hoặc thi nói). Bạn dự định luyện trả lời trước và tìm hiểu kỹ về nơi phỏng vấn. Một người lạ nhắn mời làm khảo sát nhận quà, hối trả lời ngay.", "t": [[1, "Chuẩn bị cho buổi phỏng vấn ngày mai"], [2, "Luyện trả lời trước gương hoặc với bạn"], [2, "Tìm hiểu kỹ thông tin nơi phỏng vấn"], [3, "Bỏ qua khảo sát lạ mời chào"]], "tip": "Chuẩn bị kỹ (🌱) trước một sự kiện quan trọng (🔥) luôn đi cùng nhau, không nên tách rời.", "p": "a"},
{"s": "Chiều nay có buổi họp lớp/họp nhóm quan trọng, phải đúng giờ. Giáo viên gợi ý tìm hiểu trước một chủ đề của học kỳ tới. Bạn cũng đang định xem lại bài đăng cũ trên mạng xã hội và chơi game không mục tiêu.", "t": [[1, "Tham gia buổi họp đúng giờ"], [2, "Tìm hiểu trước chủ đề học kỳ tới"], [4, "Xem lại bài đăng cũ"], [4, "Chơi game không mục tiêu", "Giải trí thuần túy, chỉ nên làm sau khi đã xong việc quan trọng."]], "tip": "Không có ⚡. Không phải ngày nào cũng có yếu tố “giả khẩn cấp”.", "p": "a"},
{"s": "Ba việc dồn cùng lúc: nộp học phí/khoản đóng góp (hạn chót hôm nay), hoàn thành bài tập nhóm nộp sáng mai, và đi kiểm tra sức khỏe định kỳ bắt buộc chiều nay. Bạn cũng muốn dành ít phút lập danh sách việc cho tuần tới.", "t": [[1, "Nộp học phí đúng hạn"], [1, "Hoàn thành bài tập nhóm"], [1, "Đi kiểm tra sức khỏe định kỳ"], [2, "Lập danh sách việc cho tuần tới"]], "tip": "Giữa ngày dồn dập 🔥, vẫn nên dành vài phút cho 🌱. Đó là dấu hiệu của người quản lý thời gian giỏi.", "p": "a"},
{"s": "Một ngày học bình thường. Chiều nay có bài tập cần nộp. Bạn muốn ôn lại kiến thức cũ định kỳ để không quên. Một bạn nhắn mượn đồ dùng học tập (không gấp lắm), và có 15 phút giải lao giữa các tiết.", "t": [[1, "Hoàn thành bài tập nộp chiều nay"], [2, "Ôn lại kiến thức cũ định kỳ"], [3, "Trả lời bạn về việc mượn đồ"], [4, "Giải lao 15 phút giữa giờ"]], "tip": "Có đủ cả 4 ô, nhưng đây không phải khuôn mẫu chung. Đừng suy ra quy luật từ một tình huống.", "p": "a"},
{"s": "Sáng mai có 2 bài kiểm tra liên tiếp ở 2 môn khác nhau. Bạn muốn xây dựng phương pháp ghi chú/ôn tập hiệu quả hơn về lâu dài. Có tin nhắn rủ dự sự kiện “chỉ hôm nay mới đăng ký được” nhưng không liên quan đến mục tiêu của bạn.", "t": [[1, "Ôn kiểm tra môn thứ nhất"], [1, "Ôn kiểm tra môn thứ hai"], [2, "Xây dựng phương pháp ghi chú/ôn tập hiệu quả hơn"], [3, "Cân nhắc kỹ, không vội đăng ký sự kiện không liên quan"]], "tip": "Không có 🗑️. Một ngày căng nhưng gọn, không có khoảng trống để giết thời gian vô ích.", "p": "h"},
{"s": "Bạn có một việc quan trọng phải xong trong hôm nay (bài tập, thủ tục hoặc việc gia đình cần xử lý gấp). Ngoài ra là cả buổi tối rảnh với 3 lựa chọn giải trí: xem phim, chơi game, lướt mạng.", "t": [[1, "Hoàn thành việc quan trọng hôm nay"], [4, "Xem phim"], [4, "Chơi game"], [4, "Lướt mạng"]], "tip": "Sau khi xong việc 🔥, cả 3 lựa chọn còn lại chỉ là giải trí. Không sai, miễn làm SAU khi đã xong việc quan trọng.", "p": "a"},
{"s": "Tuần thi cuối kỳ đang đến gần, mai thi môn đầu tiên. Bạn cần theo sát lịch ôn đã lập, duy trì ôn đều các môn còn lại, và giữ ngủ đủ giấc, ăn uống đầy đủ suốt tuần thi.", "t": [[1, "Ôn thi môn ngày mai"], [1, "Theo sát lịch ôn đã lập (đang có nguy cơ trễ)"], [2, "Duy trì ôn đều các môn còn lại"], [2, "Ngủ đủ, ăn uống đầy đủ"]], "tip": "Tuần thi dễ khiến ta bỏ quên 🌱 (sức khỏe, nhịp ôn tập). Nhưng bỏ 🌱 sẽ làm 🔥 của những ngày sau còn khó hơn.", "p": "h"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[2, "Tìm hiểu các ngành, khối thi để định hướng cuối cấp", "Còn thời gian, và định hướng sớm giúp chọn khối thi đúng."], [2, "Đọc trước bài học tuần sau", "Chưa phải làm ngay, nhưng đọc trước giúp tiếp thu bài tuần sau dễ hơn."], [3, "Người lạ mời làm khảo sát nhận quà, hối trả lời ngay", "Hối thúc để bạn không kịp nghĩ; việc này không liên quan đến bạn và có thể là lừa đảo."], [4, "Dọn phòng đang hơi bừa nhưng không ảnh hưởng gì", "Phòng hơi bừa nhưng không ảnh hưởng gì, để sau cũng được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[3, "Thông báo game mời nhận quà ngay hôm nay", "Quà trong hôm nay chỉ để kéo bạn vào chơi, bỏ qua không mất gì."], [3, "Cuộc gọi chào mời dịch vụ không cần thiết", "Chuông reo nghe có vẻ gấp, nhưng dịch vụ bạn không cần nên từ chối nhanh là xong."], [4, "Xem series phim dài tập, không giới hạn thời gian", "Không giới hạn thời gian nên dễ mất kiểm soát, để sau cũng được."], [4, "Dọn phòng đang hơi bừa nhưng không ảnh hưởng gì", "Phòng hơi bừa nhưng không ảnh hưởng gì, để sau cũng được."]], "p": "s"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[1, "Nộp phiếu đăng ký nguyện vọng, hạn chót ngày mai", "Hạn chót ngày mai, và lựa chọn này ảnh hưởng hướng học sau này."], [1, "Hoàn thành bài tập về nhà nộp tiết đầu sáng mai", "Nộp ở tiết đầu sáng mai, chỉ còn tối nay để làm."], [3, "Bạn nhắn hỏi gấp một câu có thể tự tra Google", "Câu hỏi tự tra Google được, nên trả lời gọn hoặc gợi ý bạn tự tra là đủ."], [3, "Email “chỉ hôm nay” mời mua khóa học đắt đỏ không liên quan", "Giảm giá có hạn, nhưng khóa học không liên quan thì không đáng đổi tiền hay thời gian."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[1, "Chăm người nhà đang ốm tối nay", "Người thân cần bạn ngay tối nay, việc này không dời được."], [2, "Tìm hiểu tiêu chí chọn chuyên ngành hẹp cho năm sau", "Dành cho năm sau, nên có thời gian tìm hiểu kỹ để chọn đúng."], [2, "Đọc sách mở rộng kiến thức chuyên môn", "Không bắt buộc và không có hạn, nhưng kiến thức nền có giá trị lâu dài."], [3, "Người quen nhờ việc không liên quan đến bạn, giọng rất gấp", "Giọng gấp của người khác không biến việc đó thành việc của bạn, hãy từ chối khéo."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[2, "Bắt đầu học một kỹ năng mới theo mục tiêu dài hạn", "Kết quả đến sau nhiều tuần nên không gấp, nhưng bắt đầu càng sớm càng có lợi."], [2, "Bắt đầu sớm dự án lớn, còn 3 tuần nữa mới nộp", "Còn 3 tuần, bắt đầu sớm tránh dồn cuối và có thời gian sửa."], [2, "Tập thể dục đều đặn 30 phút", "Không ai hối thúc, nhưng bỏ lâu ngày sẽ ảnh hưởng sức khỏe và khả năng tập trung."], [3, "Email “chỉ hôm nay” mời mua khóa học đắt đỏ không liên quan", "Giảm giá có hạn, nhưng khóa học không liên quan thì không đáng đổi tiền hay thời gian."]], "p": "a"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Hoàn thành sản phẩm dự án môn Công nghệ, nộp ngày mai", "Nộp ngày mai và sản phẩm quyết định điểm dự án."], [3, "Thông báo quảng cáo “giảm giá chỉ trong hôm nay”", "Khuyến mãi “chỉ hôm nay” tạo cảm giác gấp, nhưng bỏ lỡ cũng không ảnh hưởng gì đến việc học."], [3, "Lời mời chụp ảnh theo trào lưu hot, “làm ngay kẻo hết trend”", "Trend qua nhanh nhưng bỏ lỡ cũng không mất gì, đừng để nó cắt ngang việc chính."], [3, "Tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng, hối đăng ký hôm nay", "Hối “đăng ký hôm nay” là chiêu tạo cảm giác gấp, mà nhóm này chưa rõ chất lượng nên không quan trọng với mục tiêu của bạn."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Nộp đơn xin hoãn thi, hạn chót hôm nay", "Hạn chót hôm nay, quá hạn không còn được hoãn và có thể bị tính vắng thi."], [4, "Lướt mạng xã hội không mục đích", "Không có mục tiêu và dễ ngốn cả giờ mà chẳng được gì."], [4, "Chơi game không mục tiêu", "Giải trí thuần túy, chỉ nên làm sau khi đã xong việc quan trọng."], [4, "Sắp xếp lại album ảnh điện thoại", "Việc nhỏ làm lúc nào cũng được, bỏ qua cũng không sao."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[3, "Người quen nhờ việc không liên quan đến bạn, giọng rất gấp", "Giọng gấp của người khác không biến việc đó thành việc của bạn, hãy từ chối khéo."], [3, "Cuộc gọi chào mời dịch vụ không cần thiết", "Chuông reo nghe có vẻ gấp, nhưng dịch vụ bạn không cần nên từ chối nhanh là xong."], [4, "Nằm nghỉ 15 phút, không làm gì", "Nghỉ ngắn là bình thường và không gấp, chỉ thành vấn đề khi thay thế việc quan trọng."], [4, "Xem lại video giải trí đã xem nhiều lần", "Đã xem nhiều lần nên không thêm giá trị gì, bỏ lúc nào cũng được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[3, "Bạn nhắn hỏi gấp một câu có thể tự tra Google", "Câu hỏi tự tra Google được, nên trả lời gọn hoặc gợi ý bạn tự tra là đủ."], [4, "Đọc tin đồn về người nổi tiếng", "Không liên quan đến học tập hay mục tiêu của bạn."], [4, "Xem lại các bài đăng cũ trên mạng xã hội", "Không ảnh hưởng gì đến hiện tại và không có hạn."], [4, "Làm bài trắc nghiệm vui “bạn là con vật nào”", "Giải trí ngắn, không có hạn và không quan trọng."]], "p": "s"},
{"s": "Bạn đang nhìn vào danh sách việc hôm nay. Hãy phân loại chúng.", "t": [[1, "Hoàn thành bài báo cáo nhóm sắp tới giờ họp chiều nay", "Sắp tới giờ họp nhóm chiều nay, trễ sẽ làm chậm cả nhóm."], [2, "Nghỉ ngơi có kế hoạch cuối tuần, có giới hạn giờ", "Nghỉ có chủ đích, có giới hạn giờ để nạp lại năng lượng, khác với lướt vô định."], [3, "Người quen nhờ việc không liên quan đến bạn, giọng rất gấp", "Giọng gấp của người khác không biến việc đó thành việc của bạn, hãy từ chối khéo."], [4, "Xem video hài bạn bè gửi", "Vui nhưng không gấp và không đóng góp gì cho việc học."]], "p": "a"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[1, "Ôn thi học kỳ môn thi sáng mai", "Môn thi sáng mai, điểm học kỳ quan trọng và không còn thời gian khác để ôn."], [2, "Giữ giấc ngủ và bữa ăn điều độ trong tuần bận", "Thiếu ngủ kéo tụt hiệu quả học, và việc này không ai nhắc nên dễ bị bỏ quên."], [3, "Nhóm lớp hỏi link bài, đã có bạn khác trả lời rồi", "Đã có bạn khác trả lời nên bạn không cần xử lý thêm."], [4, "Chơi game không mục tiêu", "Giải trí thuần túy, chỉ nên làm sau khi đã xong việc quan trọng."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Nộp hồ sơ xin học bổng, hạn chót hôm nay", "Quá hạn là mất cơ hội hoàn toàn, mà học bổng ảnh hưởng lâu dài."], [2, "Giữ giấc ngủ và bữa ăn điều độ trong tuần bận", "Thiếu ngủ kéo tụt hiệu quả học, và việc này không ai nhắc nên dễ bị bỏ quên."], [2, "Bắt đầu học một kỹ năng mới theo mục tiêu dài hạn", "Kết quả đến sau nhiều tuần nên không gấp, nhưng bắt đầu càng sớm càng có lợi."], [2, "Luyện thuyết trình trước gương cho buổi nói tuần sau", "Còn cả tuần, luyện sớm thì ngày thuyết trình đỡ run và không phải cấp tốc."]], "p": "s"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[3, "Thông báo game mời nhận quà ngay hôm nay", "Quà trong hôm nay chỉ để kéo bạn vào chơi, bỏ qua không mất gì."], [3, "Thông báo nhóm chat dồn dập toàn chuyện phiếm", "Thông báo dồn dập khiến bạn thấy phải xem ngay, nhưng đọc gộp sau cũng không sao."], [3, "Tin nhắn dây chuyền “chuyển tiếp cho 10 người ngay”", "Lời dọa “chuyển ngay” không có căn cứ, không chuyển cũng không sao."], [4, "Làm bài trắc nghiệm vui “bạn là con vật nào”", "Giải trí ngắn, không có hạn và không quan trọng."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Hoàn thành bài báo cáo nhóm sắp tới giờ họp chiều nay", "Sắp tới giờ họp nhóm chiều nay, trễ sẽ làm chậm cả nhóm."], [3, "Thông báo quảng cáo “giảm giá chỉ trong hôm nay”", "Khuyến mãi “chỉ hôm nay” tạo cảm giác gấp, nhưng bỏ lỡ cũng không ảnh hưởng gì đến việc học."], [4, "Đổi hình nền và giao diện điện thoại", "Chỉ thay đổi cho vui, không ảnh hưởng gì."], [4, "Xem lại livestream bán hàng", "Không gấp và không mang lại gì, dễ ngốn thời gian."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[1, "Sửa bài theo góp ý của thầy cô, hạn nộp sáng mai", "Hạn sáng mai, và góp ý của thầy cô quyết định điểm cuối của bài."], [1, "Làm bài thực hành nộp trước 17h hôm nay", "Hạn 17h hôm nay và bài này lấy điểm, nên phải làm trước các việc khác."], [2, "Gọi điện trò chuyện với gia đình", "Không gấp, nhưng quan hệ gia đình cần được vun đắp đều đặn."], [3, "Thông báo game mời nhận quà ngay hôm nay", "Quà trong hôm nay chỉ để kéo bạn vào chơi, bỏ qua không mất gì."]], "p": "a"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[2, "Làm đề ôn dần cho kỳ thi cuối kỳ còn 3 tuần nữa", "Còn 3 tuần, ôn dần nhẹ nhàng hơn nhiều so với ôn dồn sát ngày thi."], [2, "Bắt đầu học một kỹ năng mới theo mục tiêu dài hạn", "Kết quả đến sau nhiều tuần nên không gấp, nhưng bắt đầu càng sớm càng có lợi."], [2, "Hỏi thầy cô/anh chị khóa trên về định hướng học tập", "Không có hạn, nhưng lời khuyên sớm giúp tránh chọn sai hướng."], [4, "Sắp xếp lại album ảnh điện thoại", "Việc nhỏ làm lúc nào cũng được, bỏ qua cũng không sao."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Nộp bài tập nhóm, hạn chót tối nay", "Hạn tối nay, và cả nhóm phụ thuộc vào phần của bạn: trễ là ảnh hưởng điểm của nhiều người."], [2, "Rèn thói quen ôn lại bài cũ định kỳ", "Ôn đều giúp nhớ lâu, nên tập thành thói quen trước khi cần thi."], [4, "Xem lại video giải trí đã xem nhiều lần", "Đã xem nhiều lần nên không thêm giá trị gì, bỏ lúc nào cũng được."], [4, "Nằm nghỉ 15 phút, không làm gì", "Nghỉ ngắn là bình thường và không gấp, chỉ thành vấn đề khi thay thế việc quan trọng."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Chuẩn bị đồ dùng và bài cho buổi thực hành sáng mai", "Thiếu đồ ở buổi thực hành sáng mai thì không làm được bài, mất điểm."], [1, "Nộp hồ sơ xin học bổng, hạn chót hôm nay", "Quá hạn là mất cơ hội hoàn toàn, mà học bổng ảnh hưởng lâu dài."], [2, "Rèn thói quen ôn lại bài cũ định kỳ", "Ôn đều giúp nhớ lâu, nên tập thành thói quen trước khi cần thi."], [4, "Xem series phim dài tập, không giới hạn thời gian", "Không giới hạn thời gian nên dễ mất kiểm soát, để sau cũng được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[2, "Tổng hợp ghi chú các bài đã học để không bị quên", "Làm dần để đỡ quên và không phải học dồn khi gần thi."], [2, "Làm CV cho kỳ thực tập mùa hè sắp mở đơn", "Đơn thực tập sắp mở, có CV chuẩn từ sớm thì không phải làm vội."], [4, "Đọc bình luận cãi nhau dưới bài viết", "Chỉ tốn thời gian và dễ bực mình, không có ích gì."], [4, "Xem video hài bạn bè gửi", "Vui nhưng không gấp và không đóng góp gì cho việc học."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[3, "Cuộc gọi chào mời dịch vụ không cần thiết", "Chuông reo nghe có vẻ gấp, nhưng dịch vụ bạn không cần nên từ chối nhanh là xong."], [3, "Tin nhắn dây chuyền “chuyển tiếp cho 10 người ngay”", "Lời dọa “chuyển ngay” không có căn cứ, không chuyển cũng không sao."], [3, "Thông báo quảng cáo “giảm giá chỉ trong hôm nay”", "Khuyến mãi “chỉ hôm nay” tạo cảm giác gấp, nhưng bỏ lỡ cũng không ảnh hưởng gì đến việc học."], [4, "Xem lại các bài đăng cũ trên mạng xã hội", "Không ảnh hưởng gì đến hiện tại và không có hạn."]], "p": "a"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[1, "Ôn kỹ cho bài kiểm tra sáng mai", "Kiểm tra sáng mai, hôm nay là thời gian ôn cuối cùng và điểm số tác động trực tiếp."], [1, "Chuẩn bị đủ giấy tờ cho buổi làm thủ tục sáng mai", "Thiếu giấy tờ sáng mai có thể phải làm lại thủ tục, mất thêm nhiều ngày."], [2, "Bắt đầu sớm dự án lớn, còn 3 tuần nữa mới nộp", "Còn 3 tuần, bắt đầu sớm tránh dồn cuối và có thời gian sửa."], [4, "Đọc bình luận cãi nhau dưới bài viết", "Chỉ tốn thời gian và dễ bực mình, không có ích gì."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[1, "Đi khám theo lịch hẹn đã đặt vào chiều nay", "Lịch hẹn đã đặt cho chiều nay, lỡ hẹn thì có thể phải chờ rất lâu và sức khỏe là việc không nên trì hoãn."], [3, "Lời mời hội thảo không liên quan đến ngành, “chỉ còn vài suất”", "“Chỉ còn vài suất” tạo áp lực, nhưng chủ đề không liên quan đến ngành của bạn."], [3, "Bạn nhắn mượn vở/tài liệu nhưng không nói khi nào cần", "Không có thời hạn, trả lời sau khi xong việc là được."], [4, "Chơi game không mục tiêu", "Giải trí thuần túy, chỉ nên làm sau khi đã xong việc quan trọng."]], "p": "s"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[2, "Tập thể dục đều đặn 30 phút", "Không ai hối thúc, nhưng bỏ lâu ngày sẽ ảnh hưởng sức khỏe và khả năng tập trung."], [2, "Lập thời gian biểu ôn tập cho tháng tới", "Chưa có hạn gấp, nhưng có kế hoạch rõ thì các việc gấp sau này sẽ đỡ dồn."], [2, "Lập kế hoạch ôn các môn còn lại trong tháng", "Chưa đến hạn, lên kế hoạch cho cả tháng giúp không bị dồn việc."], [4, "Xem video hài bạn bè gửi", "Vui nhưng không gấp và không đóng góp gì cho việc học."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[3, "Email “chỉ hôm nay” mời mua khóa học đắt đỏ không liên quan", "Giảm giá có hạn, nhưng khóa học không liên quan thì không đáng đổi tiền hay thời gian."], [3, "Người lạ mời làm khảo sát nhận quà, hối trả lời ngay", "Hối thúc để bạn không kịp nghĩ; việc này không liên quan đến bạn và có thể là lừa đảo."], [4, "Dọn phòng đang hơi bừa nhưng không ảnh hưởng gì", "Phòng hơi bừa nhưng không ảnh hưởng gì, để sau cũng được."], [4, "Làm bài trắc nghiệm vui “bạn là con vật nào”", "Giải trí ngắn, không có hạn và không quan trọng."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[1, "Ôn kỹ cho bài kiểm tra sáng mai", "Kiểm tra sáng mai, hôm nay là thời gian ôn cuối cùng và điểm số tác động trực tiếp."], [2, "Tổng hợp ghi chú các bài đã học để không bị quên", "Làm dần để đỡ quên và không phải học dồn khi gần thi."], [4, "Dọn phòng đang hơi bừa nhưng không ảnh hưởng gì", "Phòng hơi bừa nhưng không ảnh hưởng gì, để sau cũng được."], [4, "Nằm nghỉ 15 phút, không làm gì", "Nghỉ ngắn là bình thường và không gấp, chỉ thành vấn đề khi thay thế việc quan trọng."]], "p": "a"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[2, "Nghỉ ngơi có kế hoạch cuối tuần, có giới hạn giờ", "Nghỉ có chủ đích, có giới hạn giờ để nạp lại năng lượng, khác với lướt vô định."], [2, "Tham gia câu lạc bộ để rèn kỹ năng mềm", "Không có hạn gấp, nhưng giúp rèn kỹ năng mềm về lâu dài."], [3, "Bạn rủ đi ăn vặt ngay, “đi liền kẻo hết chỗ”", "“Đi liền kẻo hết chỗ” nghe gấp, nhưng chỉ là lời rủ vui, từ chối hoặc hẹn lúc khác được."], [3, "Bạn nhắn mượn vở/tài liệu nhưng không nói khi nào cần", "Không có thời hạn, trả lời sau khi xong việc là được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[2, "Học thêm Excel/SQL phục vụ nghề nghiệp sau này", "Kỹ năng nghề nghiệp cần tích lũy dần, không có hạn gấp."], [3, "Tin nhắn tuyển “cộng tác viên online” lương cao, hối nhận việc ngay", "Lương cao và hối nhận ngay là dấu hiệu đáng ngờ, không phải cơ hội cần chạy theo."], [4, "Lướt mạng xã hội không mục đích", "Không có mục tiêu và dễ ngốn cả giờ mà chẳng được gì."], [4, "Đọc bình luận cãi nhau dưới bài viết", "Chỉ tốn thời gian và dễ bực mình, không có ích gì."]], "p": "s"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[3, "Bạn nhắn hỏi gấp một câu có thể tự tra Google", "Câu hỏi tự tra Google được, nên trả lời gọn hoặc gợi ý bạn tự tra là đủ."], [3, "Cuộc gọi chào mời dịch vụ không cần thiết", "Chuông reo nghe có vẻ gấp, nhưng dịch vụ bạn không cần nên từ chối nhanh là xong."], [3, "Người quen nhờ việc không liên quan đến bạn, giọng rất gấp", "Giọng gấp của người khác không biến việc đó thành việc của bạn, hãy từ chối khéo."], [4, "Đổi hình nền và giao diện điện thoại", "Chỉ thay đổi cho vui, không ảnh hưởng gì."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[1, "Đăng ký tín chỉ trước khi hệ thống đóng tối nay", "Hệ thống đóng tối nay, không đăng ký có thể mất học phần hoặc chậm tiến độ ra trường."], [1, "Hoàn thành bài tập lớn nộp sáng mai", "Nộp sáng mai, và bài tập lớn thường có trọng số điểm cao."], [1, "Sửa bài theo góp ý của thầy cô, hạn nộp sáng mai", "Hạn sáng mai, và góp ý của thầy cô quyết định điểm cuối của bài."], [2, "Hỏi thầy cô/anh chị khóa trên về định hướng học tập", "Không có hạn, nhưng lời khuyên sớm giúp tránh chọn sai hướng."]], "p": "s"},
{"s": "Bạn đang nhìn vào danh sách việc hôm nay. Hãy phân loại chúng.", "t": [[1, "Chuẩn bị đủ giấy tờ cho buổi làm thủ tục sáng mai", "Thiếu giấy tờ sáng mai có thể phải làm lại thủ tục, mất thêm nhiều ngày."], [1, "Đi khám theo lịch hẹn đã đặt vào chiều nay", "Lịch hẹn đã đặt cho chiều nay, lỡ hẹn thì có thể phải chờ rất lâu và sức khỏe là việc không nên trì hoãn."], [3, "Thông báo nhóm chat dồn dập toàn chuyện phiếm", "Thông báo dồn dập khiến bạn thấy phải xem ngay, nhưng đọc gộp sau cũng không sao."], [3, "Lời mời chụp ảnh theo trào lưu hot, “làm ngay kẻo hết trend”", "Trend qua nhanh nhưng bỏ lỡ cũng không mất gì, đừng để nó cắt ngang việc chính."]], "p": "a"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Đóng học phí/lệ phí, hạn chót hôm nay", "Quá hạn chót có thể bị phạt hoặc ảnh hưởng quyền học, nên phải xong trong hôm nay."], [1, "Nộp bài tập nhóm, hạn chót tối nay", "Hạn tối nay, và cả nhóm phụ thuộc vào phần của bạn: trễ là ảnh hưởng điểm của nhiều người."], [4, "Xem lại livestream bán hàng", "Không gấp và không mang lại gì, dễ ngốn thời gian."], [4, "Xem lại các bài đăng cũ trên mạng xã hội", "Không ảnh hưởng gì đến hiện tại và không có hạn."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[1, "Đóng học phí/lệ phí, hạn chót hôm nay", "Quá hạn chót có thể bị phạt hoặc ảnh hưởng quyền học, nên phải xong trong hôm nay."], [1, "Gửi bản nháp đồ án cho giảng viên trước 17h hôm nay", "Phải gửi trước 17h để giảng viên kịp góp ý, trễ thì lùi cả tiến độ đồ án."], [3, "Tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng, hối đăng ký hôm nay", "Hối “đăng ký hôm nay” là chiêu tạo cảm giác gấp, mà nhóm này chưa rõ chất lượng nên không quan trọng với mục tiêu của bạn."], [3, "Thông báo nhóm chat dồn dập toàn chuyện phiếm", "Thông báo dồn dập khiến bạn thấy phải xem ngay, nhưng đọc gộp sau cũng không sao."]], "p": "s"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[1, "Đăng ký thi thử học sinh giỏi, cổng đóng tối nay", "Cổng đóng tối nay, bỏ lỡ là mất cơ hội luyện thi và xét học bổng."], [2, "Tổng hợp ghi chú các bài đã học để không bị quên", "Làm dần để đỡ quên và không phải học dồn khi gần thi."], [4, "Đọc tin đồn về người nổi tiếng", "Không liên quan đến học tập hay mục tiêu của bạn."], [4, "Lướt mạng xã hội không mục đích", "Không có mục tiêu và dễ ngốn cả giờ mà chẳng được gì."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[1, "Gia hạn chỗ ở ký túc xá trước hạn chót hôm nay", "Hết hạn hôm nay là có thể mất chỗ ở nên phải xử lý ngay."], [1, "Làm bài thực hành nộp trước 17h hôm nay", "Hạn 17h hôm nay và bài này lấy điểm, nên phải làm trước các việc khác."], [1, "Gửi email xin gia hạn deadline trước khi hết hạn tối nay", "Chỉ còn đến tối nay, hết hạn là mất luôn cơ hội xin gia hạn."], [4, "Nằm nghỉ 15 phút, không làm gì", "Nghỉ ngắn là bình thường và không gấp, chỉ thành vấn đề khi thay thế việc quan trọng."]], "p": "s"},
{"s": "Bạn đang nhìn vào danh sách việc hôm nay. Hãy phân loại chúng.", "t": [[1, "Nộp bài tập nhóm, hạn chót tối nay", "Hạn tối nay, và cả nhóm phụ thuộc vào phần của bạn: trễ là ảnh hưởng điểm của nhiều người."], [2, "Giữ giấc ngủ và bữa ăn điều độ trong tuần bận", "Thiếu ngủ kéo tụt hiệu quả học, và việc này không ai nhắc nên dễ bị bỏ quên."], [3, "Bạn nhắn hỏi gấp một câu có thể tự tra Google", "Câu hỏi tự tra Google được, nên trả lời gọn hoặc gợi ý bạn tự tra là đủ."], [3, "Người lạ mời làm khảo sát nhận quà, hối trả lời ngay", "Hối thúc để bạn không kịp nghĩ; việc này không liên quan đến bạn và có thể là lừa đảo."]], "p": "a"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[1, "Chuẩn bị cho buổi thuyết trình sáng mai", "Sáng mai là phải trình bày và chấm điểm ngay, không còn cơ hội chuẩn bị bù."], [3, "Tin nhắn dây chuyền “chuyển tiếp cho 10 người ngay”", "Lời dọa “chuyển ngay” không có căn cứ, không chuyển cũng không sao."], [4, "Dọn phòng đang hơi bừa nhưng không ảnh hưởng gì", "Phòng hơi bừa nhưng không ảnh hưởng gì, để sau cũng được."], [4, "Đọc tin đồn về người nổi tiếng", "Không liên quan đến học tập hay mục tiêu của bạn."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Ôn thi cuối kỳ môn thi sáng mai", "Thi sáng mai và điểm cuối kỳ ảnh hưởng trực tiếp đến GPA."], [1, "Chuẩn bị bảo vệ đề tài nhóm sáng mai", "Bảo vệ ngay sáng mai và điểm của cả nhóm phụ thuộc vào buổi này."], [1, "Ôn kỹ cho bài kiểm tra sáng mai", "Kiểm tra sáng mai, hôm nay là thời gian ôn cuối cùng và điểm số tác động trực tiếp."], [3, "Tin nhắn dây chuyền “chuyển tiếp cho 10 người ngay”", "Lời dọa “chuyển ngay” không có căn cứ, không chuyển cũng không sao."]], "p": "s"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[1, "Ôn bài kiểm tra 15 phút tiết đầu ngày mai", "Tuy ngắn nhưng là điểm thường xuyên và diễn ra ngay sáng mai."], [2, "Luyện thuyết trình trước gương cho buổi nói tuần sau", "Còn cả tuần, luyện sớm thì ngày thuyết trình đỡ run và không phải cấp tốc."], [2, "Tìm hiểu các học bổng, cuộc thi mở đăng ký tháng sau", "Mở đăng ký tháng sau nên chưa gấp, chuẩn bị sớm giúp hồ sơ tốt hơn."], [3, "Tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng, hối đăng ký hôm nay", "Hối “đăng ký hôm nay” là chiêu tạo cảm giác gấp, mà nhóm này chưa rõ chất lượng nên không quan trọng với mục tiêu của bạn."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[1, "Chuẩn bị phỏng vấn thực tập vào sáng mai", "Phỏng vấn sáng mai, cơ hội thực tập khó có lần thứ hai."], [1, "Chuẩn bị cho buổi thuyết trình sáng mai", "Sáng mai là phải trình bày và chấm điểm ngay, không còn cơ hội chuẩn bị bù."], [2, "Tham gia sự kiện kết nối cựu sinh viên", "Không gấp, nhưng mạng lưới quan hệ có ích khi tìm việc sau này."], [2, "Gọi điện trò chuyện với gia đình", "Không gấp, nhưng quan hệ gia đình cần được vun đắp đều đặn."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[2, "Hỏi thầy cô/anh chị khóa trên về định hướng học tập", "Không có hạn, nhưng lời khuyên sớm giúp tránh chọn sai hướng."], [2, "Rèn thói quen ôn lại bài cũ định kỳ", "Ôn đều giúp nhớ lâu, nên tập thành thói quen trước khi cần thi."], [2, "Lập kế hoạch chi tiêu cho tháng này", "Chưa gấp, nhưng giúp tránh hết tiền giữa tháng."], [4, "Đổi hình nền và giao diện điện thoại", "Chỉ thay đổi cho vui, không ảnh hưởng gì."]], "p": "a"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[3, "Thông báo nhóm chat dồn dập toàn chuyện phiếm", "Thông báo dồn dập khiến bạn thấy phải xem ngay, nhưng đọc gộp sau cũng không sao."], [4, "Chơi game không mục tiêu", "Giải trí thuần túy, chỉ nên làm sau khi đã xong việc quan trọng."], [4, "Làm bài trắc nghiệm vui “bạn là con vật nào”", "Giải trí ngắn, không có hạn và không quan trọng."], [4, "Đọc bình luận cãi nhau dưới bài viết", "Chỉ tốn thời gian và dễ bực mình, không có ích gì."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[1, "Chuẩn bị đủ giấy tờ cho buổi làm thủ tục sáng mai", "Thiếu giấy tờ sáng mai có thể phải làm lại thủ tục, mất thêm nhiều ngày."], [3, "Lời mời chụp ảnh theo trào lưu hot, “làm ngay kẻo hết trend”", "Trend qua nhanh nhưng bỏ lỡ cũng không mất gì, đừng để nó cắt ngang việc chính."], [4, "Đổi hình nền và giao diện điện thoại", "Chỉ thay đổi cho vui, không ảnh hưởng gì."], [4, "Xem series phim dài tập, không giới hạn thời gian", "Không giới hạn thời gian nên dễ mất kiểm soát, để sau cũng được."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[2, "Đọc sách mở rộng kiến thức chuyên môn", "Không bắt buộc và không có hạn, nhưng kiến thức nền có giá trị lâu dài."], [2, "Lập kế hoạch chi tiêu cho tháng này", "Chưa gấp, nhưng giúp tránh hết tiền giữa tháng."], [3, "Thông báo game mời nhận quà ngay hôm nay", "Quà trong hôm nay chỉ để kéo bạn vào chơi, bỏ qua không mất gì."], [4, "Xem lại livestream bán hàng", "Không gấp và không mang lại gì, dễ ngốn thời gian."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[2, "Lập thời gian biểu ôn tập cho tháng tới", "Chưa có hạn gấp, nhưng có kế hoạch rõ thì các việc gấp sau này sẽ đỡ dồn."], [4, "Sắp xếp lại album ảnh điện thoại", "Việc nhỏ làm lúc nào cũng được, bỏ qua cũng không sao."], [4, "Xem video hài bạn bè gửi", "Vui nhưng không gấp và không đóng góp gì cho việc học."], [4, "Đọc tin đồn về người nổi tiếng", "Không liên quan đến học tập hay mục tiêu của bạn."]], "p": "s"},
{"s": "Bạn đang nhìn vào danh sách việc hôm nay. Hãy phân loại chúng.", "t": [[1, "Chuẩn bị cho buổi thuyết trình sáng mai", "Sáng mai là phải trình bày và chấm điểm ngay, không còn cơ hội chuẩn bị bù."], [1, "Gửi email xin gia hạn deadline trước khi hết hạn tối nay", "Chỉ còn đến tối nay, hết hạn là mất luôn cơ hội xin gia hạn."], [2, "Tìm hiểu các học bổng, cuộc thi mở đăng ký tháng sau", "Mở đăng ký tháng sau nên chưa gấp, chuẩn bị sớm giúp hồ sơ tốt hơn."], [3, "Tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng, hối đăng ký hôm nay", "Hối “đăng ký hôm nay” là chiêu tạo cảm giác gấp, mà nhóm này chưa rõ chất lượng nên không quan trọng với mục tiêu của bạn."]], "p": "a"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[2, "Gọi điện trò chuyện với gia đình", "Không gấp, nhưng quan hệ gia đình cần được vun đắp đều đặn."], [3, "Bạn rủ đi ăn vặt ngay, “đi liền kẻo hết chỗ”", "“Đi liền kẻo hết chỗ” nghe gấp, nhưng chỉ là lời rủ vui, từ chối hoặc hẹn lúc khác được."], [4, "Lướt mạng xã hội không mục đích", "Không có mục tiêu và dễ ngốn cả giờ mà chẳng được gì."], [4, "Sắp xếp lại album ảnh điện thoại", "Việc nhỏ làm lúc nào cũng được, bỏ qua cũng không sao."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Nộp báo cáo thực tập, hạn chót 23h59 hôm nay", "Hạn 23h59 hôm nay, và báo cáo quyết định kết quả thực tập."], [3, "Bạn nhắn mượn vở/tài liệu nhưng không nói khi nào cần", "Không có thời hạn, trả lời sau khi xong việc là được."], [3, "Tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng, hối đăng ký hôm nay", "Hối “đăng ký hôm nay” là chiêu tạo cảm giác gấp, mà nhóm này chưa rõ chất lượng nên không quan trọng với mục tiêu của bạn."], [4, "Xem lại livestream bán hàng", "Không gấp và không mang lại gì, dễ ngốn thời gian."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Nộp đơn xin nghỉ học trước 9h sáng mai", "Phải nộp trước 9h sáng mai thì nghỉ mới hợp lệ, trễ là bị tính vắng không phép."], [1, "Sửa bài theo góp ý của thầy cô, hạn nộp sáng mai", "Hạn sáng mai, và góp ý của thầy cô quyết định điểm cuối của bài."], [2, "Làm đề ôn dần cho kỳ thi cuối kỳ còn 3 tuần nữa", "Còn 3 tuần, ôn dần nhẹ nhàng hơn nhiều so với ôn dồn sát ngày thi."], [2, "Tham gia câu lạc bộ để rèn kỹ năng mềm", "Không có hạn gấp, nhưng giúp rèn kỹ năng mềm về lâu dài."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[1, "Ôn thi cuối kỳ môn thi sáng mai", "Thi sáng mai và điểm cuối kỳ ảnh hưởng trực tiếp đến GPA."], [1, "Chuẩn bị đủ giấy tờ cho buổi làm thủ tục sáng mai", "Thiếu giấy tờ sáng mai có thể phải làm lại thủ tục, mất thêm nhiều ngày."], [2, "Tập thể dục đều đặn 30 phút", "Không ai hối thúc, nhưng bỏ lâu ngày sẽ ảnh hưởng sức khỏe và khả năng tập trung."], [4, "Xem lại các bài đăng cũ trên mạng xã hội", "Không ảnh hưởng gì đến hiện tại và không có hạn."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[1, "Nộp hồ sơ xin học bổng, hạn chót hôm nay", "Quá hạn là mất cơ hội hoàn toàn, mà học bổng ảnh hưởng lâu dài."], [1, "Chăm người nhà đang ốm tối nay", "Người thân cần bạn ngay tối nay, việc này không dời được."], [3, "Bạn nhắn mượn vở/tài liệu nhưng không nói khi nào cần", "Không có thời hạn, trả lời sau khi xong việc là được."], [4, "Lướt mạng xã hội không mục đích", "Không có mục tiêu và dễ ngốn cả giờ mà chẳng được gì."]], "p": "a"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[1, "Hoàn thành bài báo cáo nhóm sắp tới giờ họp chiều nay", "Sắp tới giờ họp nhóm chiều nay, trễ sẽ làm chậm cả nhóm."], [4, "Xem video hài bạn bè gửi", "Vui nhưng không gấp và không đóng góp gì cho việc học."], [4, "Xem lại video giải trí đã xem nhiều lần", "Đã xem nhiều lần nên không thêm giá trị gì, bỏ lúc nào cũng được."], [4, "Nằm nghỉ 15 phút, không làm gì", "Nghỉ ngắn là bình thường và không gấp, chỉ thành vấn đề khi thay thế việc quan trọng."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[2, "Lập kế hoạch chi tiêu cho tháng này", "Chưa gấp, nhưng giúp tránh hết tiền giữa tháng."], [2, "Viết đề cương khóa luận, còn 2 tháng mới nộp", "Còn 2 tháng, bắt đầu sớm để có thời gian sửa nhiều lần."], [3, "Người quen nhờ việc không liên quan đến bạn, giọng rất gấp", "Giọng gấp của người khác không biến việc đó thành việc của bạn, hãy từ chối khéo."], [3, "Tin nhắn dây chuyền “chuyển tiếp cho 10 người ngay”", "Lời dọa “chuyển ngay” không có căn cứ, không chuyển cũng không sao."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Đi khám theo lịch hẹn đã đặt vào chiều nay", "Lịch hẹn đã đặt cho chiều nay, lỡ hẹn thì có thể phải chờ rất lâu và sức khỏe là việc không nên trì hoãn."], [1, "Làm bài thực hành nộp trước 17h hôm nay", "Hạn 17h hôm nay và bài này lấy điểm, nên phải làm trước các việc khác."], [1, "Gửi email xin gia hạn deadline trước khi hết hạn tối nay", "Chỉ còn đến tối nay, hết hạn là mất luôn cơ hội xin gia hạn."], [3, "Bạn nhắn mượn vở/tài liệu nhưng không nói khi nào cần", "Không có thời hạn, trả lời sau khi xong việc là được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[1, "Đi khám theo lịch hẹn đã đặt vào chiều nay", "Lịch hẹn đã đặt cho chiều nay, lỡ hẹn thì có thể phải chờ rất lâu và sức khỏe là việc không nên trì hoãn."], [2, "Tìm hiểu các học bổng, cuộc thi mở đăng ký tháng sau", "Mở đăng ký tháng sau nên chưa gấp, chuẩn bị sớm giúp hồ sơ tốt hơn."], [2, "Nghỉ ngơi có kế hoạch cuối tuần, có giới hạn giờ", "Nghỉ có chủ đích, có giới hạn giờ để nạp lại năng lượng, khác với lướt vô định."], [3, "Thông báo nhóm chat dồn dập toàn chuyện phiếm", "Thông báo dồn dập khiến bạn thấy phải xem ngay, nhưng đọc gộp sau cũng không sao."]], "p": "s"},
{"s": "Bạn đang nhìn vào danh sách việc hôm nay. Hãy phân loại chúng.", "t": [[2, "Luyện thuyết trình trước gương cho buổi nói tuần sau", "Còn cả tuần, luyện sớm thì ngày thuyết trình đỡ run và không phải cấp tốc."], [4, "Xem lại livestream bán hàng", "Không gấp và không mang lại gì, dễ ngốn thời gian."], [4, "Làm bài trắc nghiệm vui “bạn là con vật nào”", "Giải trí ngắn, không có hạn và không quan trọng."], [4, "Chơi game không mục tiêu", "Giải trí thuần túy, chỉ nên làm sau khi đã xong việc quan trọng."]], "p": "a"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Chăm người nhà đang ốm tối nay", "Người thân cần bạn ngay tối nay, việc này không dời được."], [2, "Tìm hiểu các học bổng, cuộc thi mở đăng ký tháng sau", "Mở đăng ký tháng sau nên chưa gấp, chuẩn bị sớm giúp hồ sơ tốt hơn."], [2, "Gọi điện trò chuyện với gia đình", "Không gấp, nhưng quan hệ gia đình cần được vun đắp đều đặn."], [2, "Hỏi thầy cô/anh chị khóa trên về định hướng học tập", "Không có hạn, nhưng lời khuyên sớm giúp tránh chọn sai hướng."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Ôn kỹ cho bài kiểm tra sáng mai", "Kiểm tra sáng mai, hôm nay là thời gian ôn cuối cùng và điểm số tác động trực tiếp."], [4, "Xem lại video giải trí đã xem nhiều lần", "Đã xem nhiều lần nên không thêm giá trị gì, bỏ lúc nào cũng được."], [4, "Sắp xếp lại album ảnh điện thoại", "Việc nhỏ làm lúc nào cũng được, bỏ qua cũng không sao."], [4, "Xem video hài bạn bè gửi", "Vui nhưng không gấp và không đóng góp gì cho việc học."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Làm bài thu hoạch nộp trong chiều nay", "Nộp trong chiều nay và được chấm điểm, không còn thời gian dời."], [2, "Tìm hiểu các ngành, khối thi để định hướng cuối cấp", "Còn thời gian, và định hướng sớm giúp chọn khối thi đúng."], [2, "Nghỉ ngơi có kế hoạch cuối tuần, có giới hạn giờ", "Nghỉ có chủ đích, có giới hạn giờ để nạp lại năng lượng, khác với lướt vô định."], [2, "Đọc trước bài học tuần sau", "Chưa phải làm ngay, nhưng đọc trước giúp tiếp thu bài tuần sau dễ hơn."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[2, "Bắt đầu sớm dự án lớn, còn 3 tuần nữa mới nộp", "Còn 3 tuần, bắt đầu sớm tránh dồn cuối và có thời gian sửa."], [3, "Tin nhắn tuyển “cộng tác viên online” lương cao, hối nhận việc ngay", "Lương cao và hối nhận ngay là dấu hiệu đáng ngờ, không phải cơ hội cần chạy theo."], [4, "Xem lại các bài đăng cũ trên mạng xã hội", "Không ảnh hưởng gì đến hiện tại và không có hạn."], [4, "Đọc bình luận cãi nhau dưới bài viết", "Chỉ tốn thời gian và dễ bực mình, không có ích gì."]], "p": "s"},
{"s": "Bạn đang nhìn vào danh sách việc hôm nay. Hãy phân loại chúng.", "t": [[1, "Đóng học phí/lệ phí, hạn chót hôm nay", "Quá hạn chót có thể bị phạt hoặc ảnh hưởng quyền học, nên phải xong trong hôm nay."], [2, "Lập thời gian biểu ôn tập cho tháng tới", "Chưa có hạn gấp, nhưng có kế hoạch rõ thì các việc gấp sau này sẽ đỡ dồn."], [2, "Đọc sách mở rộng kiến thức chuyên môn", "Không bắt buộc và không có hạn, nhưng kiến thức nền có giá trị lâu dài."], [4, "Đọc tin đồn về người nổi tiếng", "Không liên quan đến học tập hay mục tiêu của bạn."]], "p": "a"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[2, "Lập kế hoạch chi tiêu cho tháng này", "Chưa gấp, nhưng giúp tránh hết tiền giữa tháng."], [3, "Thông báo quảng cáo “giảm giá chỉ trong hôm nay”", "Khuyến mãi “chỉ hôm nay” tạo cảm giác gấp, nhưng bỏ lỡ cũng không ảnh hưởng gì đến việc học."], [3, "Nhóm lớp hỏi link bài, đã có bạn khác trả lời rồi", "Đã có bạn khác trả lời nên bạn không cần xử lý thêm."], [4, "Xem lại các bài đăng cũ trên mạng xã hội", "Không ảnh hưởng gì đến hiện tại và không có hạn."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[1, "Đăng ký tín chỉ trước khi hệ thống đóng tối nay", "Hệ thống đóng tối nay, không đăng ký có thể mất học phần hoặc chậm tiến độ ra trường."], [2, "Tham gia nhóm nghiên cứu theo ngành", "Mang lại kiến thức chuyên ngành và lợi thế lâu dài, không hối thúc."], [3, "Thông báo quảng cáo “giảm giá chỉ trong hôm nay”", "Khuyến mãi “chỉ hôm nay” tạo cảm giác gấp, nhưng bỏ lỡ cũng không ảnh hưởng gì đến việc học."], [3, "Email “chỉ hôm nay” mời mua khóa học đắt đỏ không liên quan", "Giảm giá có hạn, nhưng khóa học không liên quan thì không đáng đổi tiền hay thời gian."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[2, "Luyện thuyết trình trước gương cho buổi nói tuần sau", "Còn cả tuần, luyện sớm thì ngày thuyết trình đỡ run và không phải cấp tốc."], [4, "Đổi hình nền và giao diện điện thoại", "Chỉ thay đổi cho vui, không ảnh hưởng gì."], [4, "Xem series phim dài tập, không giới hạn thời gian", "Không giới hạn thời gian nên dễ mất kiểm soát, để sau cũng được."], [4, "Xem lại video giải trí đã xem nhiều lần", "Đã xem nhiều lần nên không thêm giá trị gì, bỏ lúc nào cũng được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[1, "Hoàn thành bài tập lớn nộp sáng mai", "Nộp sáng mai, và bài tập lớn thường có trọng số điểm cao."], [2, "Bắt đầu học một kỹ năng mới theo mục tiêu dài hạn", "Kết quả đến sau nhiều tuần nên không gấp, nhưng bắt đầu càng sớm càng có lợi."], [3, "Thông báo game mời nhận quà ngay hôm nay", "Quà trong hôm nay chỉ để kéo bạn vào chơi, bỏ qua không mất gì."], [3, "Cuộc gọi chào mời dịch vụ không cần thiết", "Chuông reo nghe có vẻ gấp, nhưng dịch vụ bạn không cần nên từ chối nhanh là xong."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[1, "Chăm người nhà đang ốm tối nay", "Người thân cần bạn ngay tối nay, việc này không dời được."], [1, "Chuẩn bị cho buổi thuyết trình sáng mai", "Sáng mai là phải trình bày và chấm điểm ngay, không còn cơ hội chuẩn bị bù."], [4, "Xem series phim dài tập, không giới hạn thời gian", "Không giới hạn thời gian nên dễ mất kiểm soát, để sau cũng được."], [4, "Xem lại video giải trí đã xem nhiều lần", "Đã xem nhiều lần nên không thêm giá trị gì, bỏ lúc nào cũng được."]], "p": "a"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[2, "Bắt đầu sớm dự án lớn, còn 3 tuần nữa mới nộp", "Còn 3 tuần, bắt đầu sớm tránh dồn cuối và có thời gian sửa."], [3, "Người lạ mời làm khảo sát nhận quà, hối trả lời ngay", "Hối thúc để bạn không kịp nghĩ; việc này không liên quan đến bạn và có thể là lừa đảo."], [3, "Lời mời chụp ảnh theo trào lưu hot, “làm ngay kẻo hết trend”", "Trend qua nhanh nhưng bỏ lỡ cũng không mất gì, đừng để nó cắt ngang việc chính."], [3, "Email “chỉ hôm nay” mời mua khóa học đắt đỏ không liên quan", "Giảm giá có hạn, nhưng khóa học không liên quan thì không đáng đổi tiền hay thời gian."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Nộp hồ sơ xin học bổng, hạn chót hôm nay", "Quá hạn là mất cơ hội hoàn toàn, mà học bổng ảnh hưởng lâu dài."], [2, "Tham gia sự kiện kết nối cựu sinh viên", "Không gấp, nhưng mạng lưới quan hệ có ích khi tìm việc sau này."], [3, "Lời mời hội thảo không liên quan đến ngành, “chỉ còn vài suất”", "“Chỉ còn vài suất” tạo áp lực, nhưng chủ đề không liên quan đến ngành của bạn."], [4, "Xem lại video giải trí đã xem nhiều lần", "Đã xem nhiều lần nên không thêm giá trị gì, bỏ lúc nào cũng được."]], "p": "s"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[2, "Bắt đầu học một kỹ năng mới theo mục tiêu dài hạn", "Kết quả đến sau nhiều tuần nên không gấp, nhưng bắt đầu càng sớm càng có lợi."], [3, "Tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng, hối đăng ký hôm nay", "Hối “đăng ký hôm nay” là chiêu tạo cảm giác gấp, mà nhóm này chưa rõ chất lượng nên không quan trọng với mục tiêu của bạn."], [3, "Bạn nhắn hỏi gấp một câu có thể tự tra Google", "Câu hỏi tự tra Google được, nên trả lời gọn hoặc gợi ý bạn tự tra là đủ."], [4, "Làm bài trắc nghiệm vui “bạn là con vật nào”", "Giải trí ngắn, không có hạn và không quan trọng."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[2, "Học thêm Excel/SQL phục vụ nghề nghiệp sau này", "Kỹ năng nghề nghiệp cần tích lũy dần, không có hạn gấp."], [3, "Người lạ mời làm khảo sát nhận quà, hối trả lời ngay", "Hối thúc để bạn không kịp nghĩ; việc này không liên quan đến bạn và có thể là lừa đảo."], [3, "Lời mời chụp ảnh theo trào lưu hot, “làm ngay kẻo hết trend”", "Trend qua nhanh nhưng bỏ lỡ cũng không mất gì, đừng để nó cắt ngang việc chính."], [3, "Bạn nhắn hỏi gấp một câu có thể tự tra Google", "Câu hỏi tự tra Google được, nên trả lời gọn hoặc gợi ý bạn tự tra là đủ."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[2, "Lập thời gian biểu ôn tập cho tháng tới", "Chưa có hạn gấp, nhưng có kế hoạch rõ thì các việc gấp sau này sẽ đỡ dồn."], [3, "Bạn nhắn mượn vở/tài liệu nhưng không nói khi nào cần", "Không có thời hạn, trả lời sau khi xong việc là được."], [3, "Cuộc gọi chào mời dịch vụ không cần thiết", "Chuông reo nghe có vẻ gấp, nhưng dịch vụ bạn không cần nên từ chối nhanh là xong."], [3, "Tin nhắn dây chuyền “chuyển tiếp cho 10 người ngay”", "Lời dọa “chuyển ngay” không có căn cứ, không chuyển cũng không sao."]], "p": "a"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[1, "Chăm người nhà đang ốm tối nay", "Người thân cần bạn ngay tối nay, việc này không dời được."], [2, "Rèn thói quen ôn lại bài cũ định kỳ", "Ôn đều giúp nhớ lâu, nên tập thành thói quen trước khi cần thi."], [2, "Tập thể dục đều đặn 30 phút", "Không ai hối thúc, nhưng bỏ lâu ngày sẽ ảnh hưởng sức khỏe và khả năng tập trung."], [4, "Xem video hài bạn bè gửi", "Vui nhưng không gấp và không đóng góp gì cho việc học."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Chuẩn bị phỏng vấn thực tập vào sáng mai", "Phỏng vấn sáng mai, cơ hội thực tập khó có lần thứ hai."], [1, "Chăm người nhà đang ốm tối nay", "Người thân cần bạn ngay tối nay, việc này không dời được."], [2, "Tìm hiểu tiêu chí chọn chuyên ngành hẹp cho năm sau", "Dành cho năm sau, nên có thời gian tìm hiểu kỹ để chọn đúng."], [2, "Bắt đầu sớm dự án lớn, còn 3 tuần nữa mới nộp", "Còn 3 tuần, bắt đầu sớm tránh dồn cuối và có thời gian sửa."]], "p": "s"},
{"s": "🎒 Bạn là học sinh cuối cấp. Sau giờ học, bạn đang có những việc sau.", "t": [[1, "Nộp bài tập nhóm, hạn chót tối nay", "Hạn tối nay, và cả nhóm phụ thuộc vào phần của bạn: trễ là ảnh hưởng điểm của nhiều người."], [1, "Đi khám theo lịch hẹn đã đặt vào chiều nay", "Lịch hẹn đã đặt cho chiều nay, lỡ hẹn thì có thể phải chờ rất lâu và sức khỏe là việc không nên trì hoãn."], [1, "Gửi email xin gia hạn deadline trước khi hết hạn tối nay", "Chỉ còn đến tối nay, hết hạn là mất luôn cơ hội xin gia hạn."], [4, "Dọn phòng đang hơi bừa nhưng không ảnh hưởng gì", "Phòng hơi bừa nhưng không ảnh hưởng gì, để sau cũng được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm ba, vừa học vừa làm các hoạt động ngoài giờ. Đây là danh sách của bạn.", "t": [[1, "Chuẩn bị cho buổi thuyết trình sáng mai", "Sáng mai là phải trình bày và chấm điểm ngay, không còn cơ hội chuẩn bị bù."], [3, "Người lạ mời làm khảo sát nhận quà, hối trả lời ngay", "Hối thúc để bạn không kịp nghĩ; việc này không liên quan đến bạn và có thể là lừa đảo."], [3, "Bạn nhắn mượn vở/tài liệu nhưng không nói khi nào cần", "Không có thời hạn, trả lời sau khi xong việc là được."], [3, "Lời mời hội thảo không liên quan đến ngành, “chỉ còn vài suất”", "“Chỉ còn vài suất” tạo áp lực, nhưng chủ đề không liên quan đến ngành của bạn."]], "p": "s"},
{"s": "Bạn đang nhìn vào danh sách việc hôm nay. Hãy phân loại chúng.", "t": [[1, "Ôn kỹ cho bài kiểm tra sáng mai", "Kiểm tra sáng mai, hôm nay là thời gian ôn cuối cùng và điểm số tác động trực tiếp."], [1, "Nộp bài tập nhóm, hạn chót tối nay", "Hạn tối nay, và cả nhóm phụ thuộc vào phần của bạn: trễ là ảnh hưởng điểm của nhiều người."], [2, "Nghỉ ngơi có kế hoạch cuối tuần, có giới hạn giờ", "Nghỉ có chủ đích, có giới hạn giờ để nạp lại năng lượng, khác với lướt vô định."], [3, "Thông báo nhóm chat dồn dập toàn chuyện phiếm", "Thông báo dồn dập khiến bạn thấy phải xem ngay, nhưng đọc gộp sau cũng không sao."]], "p": "a"},
{"s": "🎒 Bạn là học sinh THPT. Hôm nay có khá nhiều thứ cần cân nhắc.", "t": [[2, "Đọc sách mở rộng kiến thức chuyên môn", "Không bắt buộc và không có hạn, nhưng kiến thức nền có giá trị lâu dài."], [2, "Tổng hợp ghi chú các bài đã học để không bị quên", "Làm dần để đỡ quên và không phải học dồn khi gần thi."], [4, "Xem lại livestream bán hàng", "Không gấp và không mang lại gì, dễ ngốn thời gian."], [4, "Xem series phim dài tập, không giới hạn thời gian", "Không giới hạn thời gian nên dễ mất kiểm soát, để sau cũng được."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm cuối. Lịch hôm nay có những việc sau.", "t": [[1, "Gửi bản nháp đồ án cho giảng viên trước 17h hôm nay", "Phải gửi trước 17h để giảng viên kịp góp ý, trễ thì lùi cả tiến độ đồ án."], [1, "Làm bài thực hành nộp trước 17h hôm nay", "Hạn 17h hôm nay và bài này lấy điểm, nên phải làm trước các việc khác."], [3, "Người quen nhờ việc không liên quan đến bạn, giọng rất gấp", "Giọng gấp của người khác không biến việc đó thành việc của bạn, hãy từ chối khéo."], [4, "Xem lại livestream bán hàng", "Không gấp và không mang lại gì, dễ ngốn thời gian."]], "p": "s"},
{"s": "🎒 Bạn là học sinh. Một ngày học bình thường, đây là mấy việc đang chờ bạn.", "t": [[2, "Lập kế hoạch ôn các môn còn lại trong tháng", "Chưa đến hạn, lên kế hoạch cho cả tháng giúp không bị dồn việc."], [2, "Lập thời gian biểu ôn tập cho tháng tới", "Chưa có hạn gấp, nhưng có kế hoạch rõ thì các việc gấp sau này sẽ đỡ dồn."], [2, "Giữ giấc ngủ và bữa ăn điều độ trong tuần bận", "Thiếu ngủ kéo tụt hiệu quả học, và việc này không ai nhắc nên dễ bị bỏ quên."], [3, "Người quen nhờ việc không liên quan đến bạn, giọng rất gấp", "Giọng gấp của người khác không biến việc đó thành việc của bạn, hãy từ chối khéo."]], "p": "h"},
{"s": "🎓 Bạn là sinh viên năm hai. Hôm nay có mấy việc cần quyết định thứ tự.", "t": [[2, "Tập thể dục đều đặn 30 phút", "Không ai hối thúc, nhưng bỏ lâu ngày sẽ ảnh hưởng sức khỏe và khả năng tập trung."], [2, "Tham gia nhóm nghiên cứu theo ngành", "Mang lại kiến thức chuyên ngành và lợi thế lâu dài, không hối thúc."], [2, "Lập thời gian biểu ôn tập cho tháng tới", "Chưa có hạn gấp, nhưng có kế hoạch rõ thì các việc gấp sau này sẽ đỡ dồn."], [3, "Tin nhắn mời vào nhóm học “cấp tốc” không rõ chất lượng, hối đăng ký hôm nay", "Hối “đăng ký hôm nay” là chiêu tạo cảm giác gấp, mà nhóm này chưa rõ chất lượng nên không quan trọng với mục tiêu của bạn."]], "p": "s"},
{"s": "Một ngày bình thường của bạn có mấy việc sau.", "t": [[1, "Làm bài thực hành nộp trước 17h hôm nay", "Hạn 17h hôm nay và bài này lấy điểm, nên phải làm trước các việc khác."], [1, "Hoàn thành bài báo cáo nhóm sắp tới giờ họp chiều nay", "Sắp tới giờ họp nhóm chiều nay, trễ sẽ làm chậm cả nhóm."], [1, "Nộp hồ sơ xin học bổng, hạn chót hôm nay", "Quá hạn là mất cơ hội hoàn toàn, mà học bổng ảnh hưởng lâu dài."], [2, "Lập kế hoạch chi tiêu cho tháng này", "Chưa gấp, nhưng giúp tránh hết tiền giữa tháng."]], "p": "a"}
];
